231→// ---------------------------------------------------------------------------
232→// Component
233→// ---------------------------------------------------------------------------
234→
235→export default function SizeCharts() {
236→  const { charts, plan, templates, categories, canCreate } =
237→    useLoaderData<typeof loader>();
238→  const fetcher = useFetcher<typeof action>();
239→  const shopify = useAppBridge();
240→
241→  const [showTemplates, setShowTemplates] = useState(false);
242→  const [categoryFilter, setCategoryFilter] = useState("all");
243→  const [statusFilter, setStatusFilter] = useState("all");
244→  const [hoveredTemplate, setHoveredTemplate] = useState<string | null>(null);
245→
246→  const isLoading = fetcher.state !== "idle";
247→
248→  useEffect(() => {
249→    if (!fetcher.data) return;
250→    const data = fetcher.data as ActionData;
251→    if ("ok" in data && data.ok) {
252→      shopify.toast.show(data.message);
253→      if ("redirectId" in data && data.redirectId) {
254→        window.location.href = `/app/size-charts/${data.redirectId}`;
