256→        setShowTemplates(false);
257→      }
258→    } else if ("error" in data) {
259→      shopify.toast.show(data.error, { isError: true });
260→    }
261→  }, [fetcher.data, shopify]);
262→
263→  const filteredCharts = charts.filter((chart) => {
264→    const matchesCategory =
265→      categoryFilter === "all" || chart.category === categoryFilter;
266→    const matchesStatus =
267→      statusFilter === "all" || chart.status === statusFilter;
268→    return matchesCategory && matchesStatus;
269→  });
270→
271→  const publishedCount = charts.filter((c) => c.status === "active").length;
272→  const maxCharts = plan.limits.maxCharts;
273→  const isFreePlan = plan.id === "free";
274→
275→  const progressPct =
276→    maxCharts > 0 ? Math.min(100, Math.round((publishedCount / maxCharts) * 100)) : 0;
277→  const progressColor = publishedCount >= maxCharts && maxCharts > 0 ? "#d72c0d" : "#1a73e8";
278→
279→  return (
280→    <s-page heading="Size Charts">
281→      {/* Primary action */}
282→      <s-button
283→        slot="primary-action"
284→        variant="primary"
285→        onClick={() => setShowTemplates(!showTemplates)}
286→        disabled={!canCreate || isLoading}
287→      >
288→        {canCreate
289→          ? showTemplates
290→            ? "Cancel"
291→            : "Create chart"
292→          : `Limit reached (${plan.limits.maxCharts})`}
293→      </s-button>
294→
295→      {/* Subtitle */}
296→      <s-text tone="neutral">
297→        Manage your size charts and assign them to products
298→      </s-text>
299→
300→      {/* ================================================================ */}
301→      {/* PLAN LIMIT BANNER                                                 */}
302→      {/* ================================================================ */}
303→      {!canCreate && (
304→        <s-section>
305→          <div
306→            style={{
307→              ...cardStyle,
308→              background: "#fff8ec",
309→              border: "1px solid #ffd79d",
310→              display: "flex",
311→              alignItems: "center",
312→              justifyContent: "space-between",
313→              gap: "16px",
314→            }}
315→          >
316→            <div>
317→              <p
318→                style={{
319→                  margin: "0 0 4px",
320→                  fontSize: "14px",
321→                  fontWeight: 600,
322→                  color: "#202223",
323→                }}
324→              >
325→                Chart limit reached
326→              </p>
327→              <p style={{ margin: 0, fontSize: "13px", color: "#6d7175" }}>
328→                You have reached the {plan.limits.maxCharts}-chart limit on the {plan.name}{" "}
329→                plan. Upgrade to Starter for unlimited charts.
330→              </p>
331→            </div>
332→            <s-button href="/app/pricing" variant="primary">
333→              Upgrade plan
334→            </s-button>
335→          </div>
336→        </s-section>
337→      )}
338→
339→      {/* ================================================================ */}
340→      {/* TEMPLATE PICKER                                                   */}
341→      {/* ================================================================ */}
342→      {showTemplates && (
343→        <s-section>
344→          <div style={cardStyle}>
345→            {/* Header */}
346→            <div
347→              style={{
348→                display: "flex",
349→                justifyContent: "space-between",
350→                alignItems: "center",
351→                marginBottom: "6px",
352→              }}
353→            >
354→              <div>
355→                <p style={sectionTitle}>Choose a starting point</p>
356→                <p style={{ fontSize: "13px", color: "#6d7175", margin: "4px 0 0" }}>
357→                  Pick a template with pre-filled sizing data, or start from scratch.
358→                </p>
359→              </div>
360→              <button
361→                onClick={() => setShowTemplates(false)}
362→                style={{
363→                  background: "none",
364→                  border: "1px solid #c9cccf",
365→                  borderRadius: "6px",
366→                  cursor: "pointer",
367→                  padding: "4px 10px",
368→                  fontSize: "13px",
369→                  color: "#6d7175",
370→                  lineHeight: "20px",
371→                }}
372→                aria-label="Close template picker"
