374→                Close
375→              </button>
376→            </div>
377→
378→            {/* Template grid */}
379→            <div
380→              style={{
381→                display: "grid",
382→                gridTemplateColumns: "repeat(auto-fill, minmax(180px, 1fr))",
383→                gap: "10px",
384→                marginTop: "16px",
385→              }}
386→            >
387→              {templates.map((template) => (
388→                <div
389→                  key={template.name}
390→                  style={{
391→                    background: "#fff",
392→                    border: `1px solid ${hoveredTemplate === template.name ? "#005bd3" : "#e3e3e3"}`,
393→                    borderRadius: "10px",
394→                    padding: "14px",
395→                    transition: "border-color 0.15s ease",
396→                  }}
