429→
430→              {/* Blank chart card */}
431→              <div
432→                style={{
433→                  background: "#f9fafb",
434→                  border: `2px dashed ${hoveredTemplate === "__blank" ? "#005bd3" : "#c9cccf"}`,
435→                  borderRadius: "10px",
436→                  padding: "14px",
437→                  transition: "border-color 0.15s ease",
438→                }}
439→                onMouseEnter={() => setHoveredTemplate("__blank")}
440→                onMouseLeave={() => setHoveredTemplate(null)}
441→              >
442→                <p
443→                  style={{
444→                    margin: "0 0 4px",
445→                    fontWeight: 600,
446→                    fontSize: "14px",
447→                    color: "#202223",
448→                  }}
449→                >
450→                  Blank Chart
