464→                  <input type="hidden" name="category" value="general" />
465→                  <s-button type="submit" loading={isLoading}>
466→                    Create Blank
467→                  </s-button>
468→                </fetcher.Form>
469→              </div>
470→            </div>
471→          </div>
472→        </s-section>
473→      )}
474→
475→      {/* ================================================================ */}
476→      {/* FILTER BAR                                                        */}
477→      {/* ================================================================ */}
478→      <s-section>
479→        <div style={cardStyle}>
480→          <div
481→            style={{
482→              display: "flex",
483→              alignItems: "center",
484→              gap: "12px",
485→              flexWrap: "wrap",
486→            }}
487→          >
488→            <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
