528→                  color: "#202223",
529→                  cursor: "pointer",
530→                  outline: "none",
531→                }}
532→              >
533→                <option value="all">All Statuses</option>
534→                <option value="active">Active</option>
535→                <option value="draft">Draft</option>
536→              </select>
537→            </div>
538→
539→            <span
540→              style={{
541→                marginLeft: "auto",
542→                fontSize: "13px",
543→                color: "#6d7175",
544→                whiteSpace: "nowrap",
545→              }}
546→            >
