571→          {charts.length === 0 && (
572→            <div style={{ textAlign: "center", padding: "48px 24px" }}>
573→              <div
574→                style={{
575→                  width: "72px",
576→                  height: "72px",
577→                  borderRadius: "50%",
578→                  background: "#f0f5ff",
579→                  margin: "0 auto 16px",
580→                  display: "flex",
581→                  alignItems: "center",
582→                  justifyContent: "center",
583→                  fontSize: "28px",
584→                }}
585→              >
586→                📐
587→              </div>
588→              <p
589→                style={{
590→                  fontSize: "15px",
591→                  fontWeight: 600,
592→                  color: "#202223",
593→                  margin: "0 0 8px",
