598→              <p
599→                style={{
600→                  fontSize: "13px",
601→                  color: "#6d7175",
602→                  margin: "0 0 20px",
603→                  maxWidth: "360px",
604→                  marginLeft: "auto",
605→                  marginRight: "auto",
606→                }}
607→              >
