611→              </p>
612→              <s-button variant="primary" onClick={() => setShowTemplates(true)}>
613→                Create your first chart
614→              </s-button>
615→            </div>
616→          )}
617→
618→          {/* Empty state — filters applied */}
619→          {charts.length > 0 && filteredCharts.length === 0 && (
620→            <div style={{ textAlign: "center", padding: "40px 24px" }}>
621→              <p
622→                style={{
623→                  fontSize: "15px",
624→                  fontWeight: 600,
625→                  color: "#202223",
626→                  margin: "0 0 8px",
627→                }}
628→              >
629→                No charts match your filters
630→              </p>
631→              <p style={{ fontSize: "13px", color: "#6d7175", margin: "0 0 16px" }}>
632→                Try changing the category or status filters above.
633→              </p>
634→              <s-button
635→                onClick={() => {
636→                  setCategoryFilter("all");
