644→
645→          {/* Chart rows */}
646→          {filteredCharts.length > 0 && (
647→            <div style={{ marginTop: "8px" }}>
648→              {filteredCharts.map((chart, i) => (
649→                <div
650→                  key={chart.id}
651→                  style={{
652→                    display: "flex",
653→                    alignItems: "center",
654→                    justifyContent: "space-between",
655→                    padding: "14px 0",
656→                    borderBottom:
