664→                  <div style={{ flex: 1, minWidth: 0 }}>
665→                    <div style={{ marginBottom: "6px" }}>
666→                      <s-link href={`/app/size-charts/${chart.id}`}>
667→                        <span
668→                          style={{
669→                            fontWeight: 600,
670→                            fontSize: "14px",
671→                            color: "#202223",
672→                          }}
673→                        >
674→                          {chart.name}
675→                        </span>
676→                      </s-link>
677→                    </div>
678→                    <div
